cat > /tmp/ReadBinlog.cs << 'EOF'
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild("/tmp/sv-984a1352edff440cb72ebd87d826fc7c/build.binlog");

Console.WriteLine($"Build succeeded: {build.Succeeded}");
Console.WriteLine();

// Collect all errors
var errors = new List<(string project, string code, string file, int line, string message)>();

build.VisitAllChildren<Error>(error =>
{
    var project = "";
    var node = error.Parent;
    while (node != null)
    {
        if (node is Project p)
        {
            project = p.Name;
            break;
        }
        node = node.Parent;
    }
    errors.Add((project, error.Code ?? "", error.File ?? "", error.LineNumber, error.Text ?? ""));
});

Console.WriteLine($"Total errors: {errors.Count}");
Console.WriteLine();

var grouped = errors.GroupBy(e => e.project);
foreach (var g in grouped)
{
    Console.WriteLine($"=== Project: {g.Key} ===");
    foreach (var e in g)
    {
        Console.WriteLine($"  [{e.code}] {e.file}({e.line}): {e.message}");
    }
    Console.WriteLine();
}
EOF

