using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild("/tmp/sv-984a1352edff440cb72ebd87d826fc7c/build.binlog");

// Check if Api had MSB errors due to dependency failure
Console.WriteLine("=== Messages with 'failed' or 'skipping' ===");
build.VisitAllChildren<Message>(m =>
{
    if (m.Text != null && (m.Text.Contains("failed") || m.Text.Contains("not build") || m.Text.Contains("skipp")))
    {
        var project = "";
        var node = m.Parent;
        while (node != null)
        {
            if (node is Project p) { project = p.Name; break; }
            node = node.Parent;
        }
        Console.WriteLine($"  {project}: {m.Text}");
    }
});

// Check the project.assets.json to see if Newtonsoft.Json is there
Console.WriteLine("\n=== Services/obj/project.assets.json (checking for Newtonsoft) ===");
var sourceFiles = build.SourceFiles;
foreach (var f in sourceFiles)
{
    if (f.FullPath.Contains("Services/obj/project.assets.json"))
    {
        var text = f.Text;
        Console.WriteLine($"Contains Newtonsoft: {text.Contains("Newtonsoft")}");
        Console.WriteLine($"File length: {text.Length}");
        // Show package references
        if (text.Contains("Newtonsoft"))
            Console.WriteLine("Newtonsoft IS in assets");
        else
            Console.WriteLine("Newtonsoft is NOT in assets - MISSING PACKAGE REFERENCE");
    }
}
EOF
